def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_condition(n):
    # Check P(n) = S(n)S(n+1)...S(n+37) not divisible by 11
    # This is true if and only if S(k) is not divisible by 11 for all k in [n, n+37]

    # Check divisibility by 11 for all 38 consecutive numbers
    for k in range(n, n + 38):
        s_k = sum_digits(k)
        if s_k % 11 == 0:
            return False # Product is divisible by 11
    return True # Product is not divisible by 11

# Search up to n = 5000
N_MAX = 5000
smallest_n = None

for n in range(1, N_MAX + 1):
    if check_condition(n):
        smallest_n = n
        break

print(f"The smallest n found within the first {N_MAX} tests is: {smallest_n}")

